1	#!/usr/bin/env node
2	// SessionStart step: run every ACTIVE pack's own `session-start.mjs` and forward
3	// what it prints into the session context.
4	//
5	// THE SYMMETRIC HALF OF THE SessionEnd RUNNER (engine/hooks/session-end-command.mjs),
6	// on the same terms: a step is discovered STRUCTURALLY — a pack ships the file or it
7	// doesn't — activation-gated by the repo's declaration, bounded, and fail-soft. Core
8	// never names the pack whose step it runs and never learns what one does. The one
9	// difference is the direction the output travels: a session-end step's output is a
10	// log line, and a session-start step's output IS the contribution, so it is forwarded
11	// to stdout (which SessionStart adds to the session context).
12	//
13	// WHY IT EXISTS AT ALL, given pack prose already loads every session: prose is a
14	// FILE, fixed at vendor time and identical for every repo and every person that
15	// mounts it. Some pack content can only be known when the session starts — content
16	// that lives outside this repo, or that is keyed to the person in front of it. A
17	// pack that needs that has, until now, had nowhere to put it: its choices were a
18	// static file that cannot say the thing, or a core step that names the pack, which
19	// is the coupling the pack system exists to prevent. This closes that gap once,
20	// generically, rather than growing a bespoke core step per pack.
21	//
22	// THE COST IT IMPOSES, and the two bounds that keep it honest. A step is a
23	// subprocess on the session-start path, and its output lands in a finite context
24	// window. So: every step is killed at CLAUDINITE_PACK_STEP_TIMEOUT_MS, and its
25	// contribution is capped at CLAUDINITE_PACK_STEP_MAX_BYTES with the truncation
26	// stated in the injected text. Neither is a knob a pack can raise — they are the
27	// engine's terms for lending out the session's start.
28	//
29	// PLAIN TEXT ONLY, like every other step: one hook's stdout must never mix JSON and
30	// prose, and nothing here may emit a halt directive on a step's behalf. A step that
31	// fails, hangs, or exits non-zero yields one note naming the pack, and the session
32	// proceeds — exit 0, always, because a non-zero exit makes Claude Code discard the
33	// orchestrator's whole stdout, including the steps that did work.
34	//
35	// THE FACET CHANNEL. A step may also state one short phrase about what it loaded —
36	// `CLAUDINITE-FACET: 7 personal preference rules` on a line of its own. Those lines
37	// are lifted out of the step's contribution and appended to the file
38	// CLAUDINITE_SESSION_FACETS names, where the summary step (session-summary.mjs)
39	// folds them into the one line a session opens with. It rides the step, and not a
40	// manifest field, because the facts worth stating are the ones a pack had to
41	// COMPUTE at session time — a static count is already in the prose the reader has.
42	// No channel configured, or a file that cannot be written: the facet is dropped and
43	// the step's own contribution is unaffected.
44	import { existsSync, readFileSync, appendFileSync } from 'node:fs';
45	import { join, dirname } from 'node:path';
46	import { fileURLToPath } from 'node:url';
47	import { spawnSync } from 'node:child_process';
48	
49	// The file an active pack contributes, if it ships one. Named for when it runs, and
50	// deliberately the mirror of the session-end runner's STEP_FILE.
51	export const STEP_FILE = 'session-start.mjs';
52	
53	// Bounds, overridable only for tests (the env names are the engine's, not a pack's).
54	const TIMEOUT_MS = Number(process.env.CLAUDINITE_PACK_STEP_TIMEOUT_MS) || 20_000;
55	const MAX_BYTES = Number(process.env.CLAUDINITE_PACK_STEP_MAX_BYTES) || 32_768;
56	
57	const note = (s) => process.stdout.write(`PACK STEP: ${s}\n`);
58	
59	async function main() {
60	  const loaderDir = dirname(fileURLToPath(import.meta.url)); // <corpus>/engine/pack_loader
61	  const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
62	
63	  let config = { packs: [] };
64	  const configPath = join(projectRoot, '.claudinite-checks.json');
65	  if (existsSync(configPath)) {
66	    try { config = JSON.parse(readFileSync(configPath, 'utf8')); } catch { return; } // unparsable settings are the world runner's finding
67	  }
68	
69	  const { loadPacks, isActive, packEntryId } = await import(join(loaderDir, 'pack-registry.mjs'));
70	  const packs = (await loadPacks({ localRoot: projectRoot })).filter((p) => isActive(p, config));
71	  if (!packs.length) return; // this repo runs no Claudinite, or declares nothing — say nothing
72	
73	  // Each entry's own `config`, keyed by bare pack id: a step is handed its pack's
74	  // parameters rather than re-reading and re-normalizing the declaration itself.
75	  // Read here, from the raw file, because the step runs before anything else has
76	  // loaded the settings — and because one reader beats one per pack.
77	  const entryConfig = new Map();
78	  for (const entry of Array.isArray(config.packs) ? config.packs : []) {
79	    if (entry && typeof entry === 'object' && entry.config) entryConfig.set(packEntryId(entry), entry.config);
80	  }
81	
82	  for (const pack of packs) {
83	    const step = join(pack.dir, STEP_FILE);
84	    if (!existsSync(step)) continue;
85	
86	    const run = spawnSync(process.execPath, [step], {
87	      cwd: projectRoot,
88	      encoding: 'utf8',
89	      timeout: TIMEOUT_MS,
90	      maxBuffer: MAX_BYTES * 4, // room to notice an over-cap step rather than erroring on it
91	      env: {
92	        ...process.env,
93	        // What the pack declared about itself, verbatim. `{}` and not undefined: a
94	        // step should branch on what its config SAYS, never on whether the engine
95	        // remembered to hand it one.
96	        CLAUDINITE_PACK_CONFIG: JSON.stringify(entryConfig.get(pack.id) ?? {}),
97	        CLAUDINITE_PACK_DIR: pack.dir,
98	      },
99	    });
100	
101	    // A step that outran the read buffer is OVER CAP, not broken: it is the cap's
102	    // case, so it is truncated like any other over-cap step rather than reported as
103	    // a failure — and the buffer is set above the cap precisely so this branch means
104	    // "far too much", never "slightly over". Decided FIRST, because overrunning the
105	    // buffer also kills the child, which would otherwise read as a timeout.
106	    const overflowed = run.error?.code === 'ENOBUFS';
107	    if (!overflowed && (run.error?.code === 'ETIMEDOUT' || run.signal)) {
108	      note(`the "${pack.id}" pack's ${STEP_FILE} did not finish in ${Math.round(TIMEOUT_MS / 1000)}s and was stopped — continuing without what it would have said.`);
109	      continue;
110	    }
111	    if (!overflowed && run.status !== 0) {
112	      // Its output is not injected: a step that exited non-zero has said something
113	      // unfinished, and half a contribution read as a whole one is worse than none.
114	      const why = (run.stderr || '').trim().split('\n').pop() || `exit ${run.status}`;
115	      note(`the "${pack.id}" pack's ${STEP_FILE} failed (${why}) — continuing without what it would have said.`);
116	      continue;
117	    }
118	
119	    // Lift the facet lines out FIRST: they address the summary step, not the
120	    // reader, and a step that said nothing else has still said something.
121	    const facets = [];
122	    const text0 = (run.stdout || '').split('\n')
123	      .filter((line) => {
124	        const m = /^CLAUDINITE-FACET:\s*(.+?)\s*$/.exec(line);
125	        if (m) facets.push(m[1]);
126	        return !m;
127	      })
128	      .join('\n');
129	    if (facets.length && process.env.CLAUDINITE_SESSION_FACETS) {
130	      try { appendFileSync(process.env.CLAUDINITE_SESSION_FACETS, `${facets.join('\n')}\n`); } catch { /* no channel, no facet */ }
131	    }
132	
133	    let text = text0.trim();
134	    if (!text) continue; // nothing to say is a legitimate answer, and gets no marker
135	    if (overflowed || Buffer.byteLength(text, 'utf8') > MAX_BYTES) {
136	      text = `${Buffer.from(text, 'utf8').subarray(0, MAX_BYTES).toString('utf8')}\n\n[truncated at ${MAX_BYTES} bytes — the "${pack.id}" pack's ${STEP_FILE} produced more session context than a step may contribute]`;
137	    }
138	    // The same marker the prose injector uses, so a reader can tell which pack is
139	    // talking whether the text came from a file or from a step.
140	    process.stdout.write(`<!-- pack:${pack.id} -->\n${text}\n\n`);
141	  }
142	}
143	
144	// Fail-soft to the end: a broken registry, an unreadable pack tree, anything —
145	// one note, exit 0.
146	main()
147	  .catch((e) => note(`the pack session-start runner could not complete (${e.message}) — continuing.`))
148	  .finally(() => process.exit(0));
149

