1	// This pack's session-start step: fetch the current user's personal interaction
2	// preferences from the store this repo points at, and print them into the session
3	// context. The engine runs it (engine/pack_loader/run-pack-session-start.mjs) because
4	// this pack ships the file; it knows nothing about what the file does.
5	//
6	// WHY THIS IS A STEP AND NOT PROSE. `RULES.md` is fixed at vendor time and identical
7	// for every repo and every person that mounts it. What this pack contributes is
8	// neither: it belongs to the person in front of the session, and it lives in another
9	// repository entirely. Only something that runs at session start can say it.
10	//
11	// WHY THE CONTENT IS NOT HERE. Personal preferences belong to a group of people, not
12	// to a project and not to the shared canon — which every fleet mounts, and which is
13	// therefore both the wrong host for one group's preferences and the wrong authority
14	// on where they live. So this pack carries the ADDRESS (its entry `config`, read via
15	// store.mjs) and the group carries the content.
16	//
17	// LOCAL FIRST. When this tree IS the store, the working copy is what the owner is
18	// reading and editing — a fetch would serve the default branch and quietly hide the
19	// edit in progress.
20	//
21	// FAIL-SOFT ON EVERY MISS. No identity, no configured store, no file, a fetch that
22	// fails: one plain-text note, and the session proceeds on default interaction
23	// behavior. Nothing here is load-bearing — the packs, checks and skills a session
24	// needs are already local — and a halt directive over a nice-to-have would be a
25	// pack deciding the session cannot start.
26	
27	import { existsSync, readFileSync } from 'node:fs';
28	import { join } from 'node:path';
29	import { resolveStore, fileFor, isUsableIdentity } from './store.mjs';
30	
31	const FETCH_TIMEOUT_MS = 15_000;
32	const FETCH_ATTEMPTS = 3;
33	
34	const note = (s) => process.stdout.write(`USER PREFERENCES: ${s}\n`);
35	
36	// How many preferences this person actually has, stated on the engine's facet
37	// channel (engine/pack_loader/run-pack-session-start.mjs) so the session's opening
38	// summary can say it. One distilled preference per bullet is the store's rule, so
39	// the bullets ARE the count — and this step is the only thing in the session that
40	// can take it, since the file it read lives in another repository.
41	const facet = (text) => {
42	  const n = text.split('\n').filter((line) => /^\s*[-*]\s+\S/.test(line)).length;
43	  if (n) process.stdout.write(`CLAUDINITE-FACET: ${n} personal preference rule${n === 1 ? '' : 's'}\n`);
44	};
45	
46	const emit = (s) => { facet(s); process.stdout.write(s.endsWith('\n') ? s : `${s}\n`); process.exit(0); };
47	
48	// Strip quotes/backslashes before embedding an identity in a message, so an unusual
49	// one stays tidy in the injected text.
50	const safe = (s) => String(s).replace(/["\\]/g, '');
51	
