import { test } from 'node:test';
import assert from 'node:assert/strict';
import { countWords, tokensFromWords, estimateTokens } from '../../engine/pack_loader/estimate-tokens.mjs';

// The estimator behind every "how much is in the window" figure a session states —
// the corpus prose in the summary line, and whatever an active pack weighs on the
// facet channel. It is shared rather than copied because the RATIO is the thing that
// must not drift: two call sites quoting tokens at two different exchange rates would
// each be defensible alone and incomparable in the one line that prints them both.

test('words are counted across any whitespace, and nothing else counts', () => {
  assert.equal(countWords('one two three'), 3);
  assert.equal(countWords('  leading and trailing  \n\n line breaks \t tabs '), 6);
  assert.equal(countWords(''), 0);
  assert.equal(countWords('   \n \t '), 0);
});

test('tokens are words at the standard ratio, rounded to a sense of scale', () => {
  // 2250 words / 0.75 = 3000 tokens exactly — the figure the session-summary
  // fixture is built to produce, so the two tests describe one arithmetic.
  assert.equal(tokensFromWords(2250), 3000);
  assert.equal(tokensFromWords(2200), 3000); // rounded to the nearest 500
  assert.equal(estimateTokens('word '.repeat(2250)), 3000);
});

test('nothing reads as zero; something never does', () => {
  // The distinction the rounding would otherwise destroy: 0 means the pack shipped
  // no prose at all, and a session states that truthfully. But a small file rounding
  // DOWN to 0 would say the same thing about content that is really there — so the
  // rounding unit is also the floor for anything non-empty.
  assert.equal(tokensFromWords(0), 0);
  assert.equal(estimateTokens(''), 0);
  assert.equal(estimateTokens('   \n  '), 0);
  assert.equal(tokensFromWords(1), 500);
});

test('a caller states the precision its magnitude deserves', () => {
  // 500 suits a corpus of tens of thousands; a few hundred tokens of personal
  // preferences would be rounded into noise (or into the floor) by it.
  assert.equal(tokensFromWords(330, { rounding: 50 }), 450);
  assert.equal(tokensFromWords(1, { rounding: 50 }), 50);
  assert.equal(tokensFromWords(0, { rounding: 50 }), 0);
  assert.equal(estimateTokens('word '.repeat(330), { rounding: 50 }), 450);
});

