input.content:
// The one estimator behind every "how much of this session's window did the load
// take" figure — the active packs' prose in the summary line
// (engine/pack_loader/session-summary.mjs), and whatever an active pack weighs onto
// the facet channel beside it.
//
// SHARED RATHER THAN COPIED, because the RATIO is what must not drift. Two call
// sites quoting tokens at two different exchange rates would each be defensible
// alone and incomparable in the one line that prints them both.
//
// TOKENS, because that is the unit of the cost — a context window, not a disk. The
// estimate goes through WORDS at the standard English ratio: prose is words, and a
// character count is thrown off by exactly what this corpus is full of — code
// fences, paths, punctuation-dense Markdown.
export const WORDS_PER_TOKEN = 0.75;

// The default precision, sized for the corpus: tens of thousands of tokens, where a
// session summary is a sense of scale rather than an accounting. A caller weighing
// something smaller passes its own.
export const DEFAULT_ROUNDING = 500;

export const countWords = (text) => text.trim().split(/\s+/).filter(Boolean).length;

/**
 * Rounded token estimate for a word count. Zero is reserved for GENUINELY nothing:
 * the rounding unit is also the floor, so content too small to round up to it is
 * still reported as present rather than collapsing into the same figure a pack with
 * no prose at all produces.
 */
export function tokensFromWords(words, { rounding = DEFAULT_ROUNDING } = {}) {
  if (!words) return 0;
  return Math.max(rounding, Math.round(words / WORDS_PER_TOKEN / rounding) * rounding);
}

export const estimateTokens = (text, options) => tokensFromWords(countWords(text), options);

