import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { resolveStore, fileFor, isUsableIdentity } from './store.mjs';
import { estimateTokens } from '../../engine/pack_loader/estimate-tokens.mjs';

const FETCH_TIMEOUT_MS = 15_000;
const FETCH_ATTEMPTS = 3;

// Finer than the engine's default, which is sized for a corpus of tens of thousands
// of tokens: at that precision a whole preferences file is a rounding error.
const FACET_ROUNDING = 50;

const note = (s) => process.stdout.write(`USER PREFERENCES: ${s}\n`);

// What these preferences cost the session, stated on the engine's facet channel
// (engine/pack_loader/run-pack-session-start.mjs) so the opening summary can say it
// beside the corpus prose it sits next to — the same unit, from the same estimator,
// because the two are spent against the same window. This step is the only thing in
// the session that can weigh them: the file it read lives in another repository.
const facet = (text) => {
  const tokens = estimateTokens(text, { rounding: FACET_ROUNDING });
  if (tokens) process.stdout.write(`CLAUDINITE-FACET: ${tokens.toLocaleString('en-US')} personal preference tokens\n`);
};

